/* ================= B1: Vertiefungen ================= */
L("b1-conj1","b1-conj1-2","Conjuntivo: unregelmäßige Formen",[
c("saber","wissen"),c("haver","geben (es gibt)"),c("a solução","die Lösung"),c("a resposta","die Antwort"),
m("Espero que tu ___ a resposta. (saber)","saibas|sabes|sabias","saber → saiba, saibas, saiba, saibamos, saibam."),m("É importante que ___ uma solução. (haver)","haja|há|houve","haver → haja."),m("Quero que vocês ___ felizes. (ser)","sejam|são|estejam","ser → seja, sejas, seja, sejamos, sejam."),m("Espero que ela me ___ a verdade. (dizer)","diga|diz|disse","dizer → digo → diga."),m("Talvez eles ___ amanhã. (vir)","venham|vêm|vieram","vir → venho → venha, venham."),m("É preciso que tu ___ a mesa. (pôr)","ponhas|pões|pusesses","pôr → ponho → ponha, ponhas."),
l("Espero que saibas a resposta","Ich hoffe, du weißt die Antwort|Ich weiß, dass du die Antwort kennst|Ich hoffe, ich weiß die Antwort"),l("Talvez haja uma solução","Vielleicht gibt es eine Lösung|Es gibt sicher eine Lösung|Es gab eine Lösung"),
r("A chefe quer que todos venham à reunião amanhã. Espera que alguém saiba resolver o problema e que haja uma solução antes de sexta.","Was hofft die Chefin?","Dass es vor Freitag eine Lösung gibt|Dass niemand kommt|Dass die Besprechung ausfällt"),
w("Ich hoffe, dass du die Antwort weißt.","Espero que saibas a resposta.|Espero que tu saibas a resposta."),w("Vielleicht kommen sie morgen.","Talvez venham amanhã.|Talvez eles venham amanhã.|Talvez elas venham amanhã."),w("Ich will, dass ihr glücklich seid.","Quero que sejam felizes.|Quero que vocês sejam felizes.|Eu quero que vocês sejam felizes.")],
"Merkhilfe: Die meisten unregelmäßigen Formen kommen von der eu-Form im Präsens: digo → diga, faço → faça, tenho → tenha, venho → venha, ponho → ponha, posso → possa. Ganz eigene Formen haben nur: ser → seja, estar → esteja, ir → vá, saber → saiba, querer → queira, haver → haja, dar → dê.");
L("b1-conj1","b1-conj1-3","Conjuntivo: Ratschläge, Bitten & Wünsche",[
c("pedir que","bitten, dass"),c("aconselhar","raten"),c("sugerir","vorschlagen"),c("Bom fim de semana!","Schönes Wochenende!"),
m("O médico aconselha que eu ___ mais. (dormir)","durma|durmo|dormir","dormir → durmo → durma."),m("Peço-te que não ___ tarde. (chegar)","chegues|chegas|chegaste","chegar → chegue, chegues (g → gu)."),m("Sugiro que ___ ao cinema. (ir, nós)","vamos|fomos|íamos","ir → vá, vás, vá, vamos, vão."),m("Que ___ um bom dia! (ter, tu)","tenhas|tens|tiveste","Wunschformel: Que + Conjuntivo."),m("Oxalá não ___ amanhã! (chover)","chova|chove|choveu","oxalá + Conjuntivo."),m("A professora pede que os alunos ___ o livro. (abrir)","abram|abrem|abriram","abrir → abra, abram."),
l("Que tenhas um bom dia!","Hab einen schönen Tag!|Du hattest einen schönen Tag!|Was für ein schöner Tag!"),l("Peço-te que venhas","Ich bitte dich zu kommen|Ich komme zu dir|Ich frage, ob du kommst"),
r("Querida Inês, o médico aconselha que descanses e que bebas muita água. Peço-te que não vás trabalhar amanhã. Espero que melhores depressa! Um beijinho, Rita.","Was rät der Arzt?","Ausruhen und viel Wasser trinken|Arbeiten gehen|Sport treiben"),
w("Hab einen schönen Tag!","Que tenhas um bom dia!|Tem um bom dia!"),w("Hoffentlich regnet es nicht.","Oxalá não chova.|Espero que não chova.|Tomara que não chova."),w("Ich bitte dich zu kommen.","Peço-te que venhas.|Peço que venhas.|Eu peço-te que venhas.")]);

L("b1-conj2","b1-conj2-2","Conjuntivo: damit, bis, ohne dass",[
c("até que","bis"),c("sem que","ohne dass"),c("a não ser que","es sei denn"),c("desde que","vorausgesetzt, dass"),
m("Espero aqui até que tu ___. (voltar)","voltes|voltas|voltaste","até que + Conjuntivo."),m("Vou sair sem que ninguém me ___. (ver)","veja|vê|via","sem que + Conjuntivo: ver → vejo → veja."),m("Vou à praia, a não ser que ___. (chover)","chova|chove|choveu","a não ser que + Conjuntivo."),m("Podes ir, desde que ___ cedo. (voltar)","voltes|voltas|voltar","desde que (vorausgesetzt) + Conjuntivo."),m("Explico outra vez para que vocês ___. (perceber)","percebam|percebem|perceberam","para que + Conjuntivo."),m("Vamos sair antes que ___ tarde. (ser)","seja|é|for","antes que + Conjuntivo: seja."),
l("Espero até que voltes","Ich warte, bis du zurückkommst|Ich warte, weil du zurückkommst|Du wartest, bis ich zurückkomme"),l("A não ser que chova","Es sei denn, es regnet|Weil es regnet|Obwohl es regnet"),
r("A mãe do Rui diz: podes ir à festa, desde que voltes antes da meia-noite. Eu espero acordada até que chegues. E leva o casaco, a não ser que queiras ficar constipado!","Unter welcher Bedingung darf Rui zur Party?","Er muss vor Mitternacht zurück sein|Er muss Hausaufgaben machen|Er muss die Mutter mitnehmen"),
w("Ich warte, bis du zurückkommst.","Espero até que voltes.|Eu espero até que voltes.|Espero até tu voltares."),w("Es sei denn, es regnet.","A não ser que chova."),w("Du kannst gehen, vorausgesetzt du kommst früh zurück.","Podes ir, desde que voltes cedo.|Podes ir desde que voltes cedo.")],
"Achtung: „desde que“ heißt mit Conjuntivo „vorausgesetzt, dass“, mit Indikativ „seit“: Desde que moro aqui … = Seit ich hier wohne …");
L("b1-conj2","b1-conj2-3","Indikativ oder Conjuntivo?",[
c("ter a certeza","sicher sein"),c("é verdade que","es stimmt, dass"),c("é possível que","es ist möglich, dass"),c("parece que","es scheint, dass"),
m("Sei que ele ___ em casa.","está|esteja|estar","Sicheres Wissen (sei que) → Indikativ."),m("Duvido que ele ___ em casa.","esteja|está|estar","Zweifel (duvido que) → Conjuntivo."),m("É verdade que ela ___ médica.","é|seja|for","Feststellung (é verdade que) → Indikativ."),m("Não é verdade que ela ___ médica.","seja|é|era","Verneinte Feststellung → Conjuntivo."),m("Tenho a certeza de que ___ razão. (ter, tu)","tens|tenhas|tiveres","Sicherheit → Indikativ."),m("É possível que ___ amanhã. (nevar)","neve|neva|nevou","Möglichkeit → Conjuntivo: nevar → neve."),m("Acho que o filme ___ bom.","é|seja|for","Bejahte Meinung (acho que) → Indikativ."),
l("Tenho a certeza de que vem","Ich bin sicher, dass er kommt|Ich bezweifle, dass er kommt|Ich hoffe, dass er kommt"),l("É possível que chova","Es ist möglich, dass es regnet|Es regnet sicher|Es hat geregnet"),
r("O Pedro acha que o restaurante é caro, mas a Rita não acha que seja caro. Ela tem a certeza de que a comida é ótima. É possível que vão lá no sábado.","Was denkt Rita über das Restaurant?","Es ist nicht teuer und das Essen ist sehr gut|Es ist zu teuer|Das Essen ist schlecht"),
w("Ich weiß, dass er zu Hause ist.","Sei que ele está em casa.|Eu sei que ele está em casa."),w("Ich bezweifle, dass er zu Hause ist.","Duvido que ele esteja em casa.|Eu duvido que ele esteja em casa."),w("Ich glaube nicht, dass es teuer ist.","Não acho que seja caro.|Eu não acho que seja caro.|Não creio que seja caro.")],
"Faustregel: Wissen, Sicherheit und bejahte Meinung → Indikativ (sei que, tenho a certeza de que, acho que). Zweifel, Möglichkeit, Gefühl und verneinte Meinung → Conjuntivo (duvido que, é possível que, não acho que).");

L("b1-perfimp","b1-perfimp-2","Erzählen: Hintergrund & Ereignis",[
c("enquanto","während"),c("de repente","plötzlich"),c("tocar","klingeln; berühren"),c("partir","zerbrechen; abreisen"),
m("Eu ___ a dormir quando o telefone tocou.","estava|estive|estou","Laufende Handlung im Hintergrund: estava a + Infinitiv."),m("Enquanto ela cozinhava, ele ___ a mesa. (pôr)","punha|pôs|põe","Zwei gleichzeitige Hintergrundhandlungen → Imperfeito."),m("Quando cheguei, ___ muito frio. (fazer)","fazia|fez|faz","Beschreibung der Situation → Imperfeito."),m("De repente, o copo ___. (cair)","caiu|caía|cai","Plötzliches Ereignis → Perfeito."),m("Estávamos a jantar quando a luz ___. (falhar)","falhou|falhava|falha","Das Ereignis, das den Hintergrund unterbricht → Perfeito."),m("Eram dez horas e ___ a chover.","estava|esteve|está","Uhrzeit und Wetter als Kulisse → Imperfeito."),
l("Estava a dormir quando tocou o telefone","Ich schlief, als das Telefon klingelte|Ich schlief ein, als das Telefon klingelte|Das Telefon klingelte, als ich aufwachte"),l("De repente começou a chover","Plötzlich fing es an zu regnen|Es regnete den ganzen Tag|Es hörte plötzlich auf zu regnen"),
r("Era sábado e fazia sol. Eu estava a ler na varanda e o meu vizinho estava a cortar a relva. De repente, ouvimos um barulho enorme: o gato tinha partido um vaso!","Was machte der Nachbar?","Er mähte den Rasen|Er las|Er kochte"),
w("Ich schlief, als das Telefon klingelte.","Estava a dormir quando o telefone tocou.|Eu estava a dormir quando o telefone tocou.|Dormia quando o telefone tocou.|Estava a dormir quando tocou o telefone."),w("Plötzlich fing es an zu regnen.","De repente começou a chover."),w("Es war zehn Uhr.","Eram dez horas.|Eram dez.")]);
L("b1-perfimp","b1-perfimp-3","Vorvergangenheit: tinha + Partizip",[
c("já tinha","hatte schon"),c("ainda não tinha","hatte noch nicht"),c("perder o comboio","den Zug verpassen"),c("acabar de","gerade getan haben"),
m("Quando cheguei, o comboio já ___ partido.","tinha|tive|tem","Vorvergangenheit: tinha + Partizip."),m("Ela nunca ___ visto o mar antes.","tinha|teve|tem","tinha visto = hatte gesehen."),m("Nós já ___ jantado quando eles chegaram.","tínhamos|tivemos|temos","nós → tínhamos."),m("Ele disse que ___ perdido as chaves.","tinha|tem|teve","Indirekte Rede über etwas noch Früheres → tinha + Partizip."),m("Acabei ___ chegar. (gerade)","de|a|que","acabar de + Infinitiv = gerade getan haben."),m("Eu ainda não tinha ___ o livro. (ler)","lido|lendo|lia","Partizip von ler: lido."),
l("O comboio já tinha partido","Der Zug war schon abgefahren|Der Zug fährt gleich ab|Der Zug ist nicht abgefahren"),l("Acabei de chegar","Ich bin gerade angekommen|Ich komme gleich an|Ich bin nicht angekommen"),
r("Ontem perdi o comboio. Quando cheguei à estação, ele já tinha partido. Tinha saído de casa tarde, porque me tinha esquecido do telemóvel. Apanhei o seguinte e cheguei uma hora atrasado.","Warum verließ die Person das Haus zu spät?","Sie hatte das Handy vergessen|Der Wecker klingelte nicht|Sie hatte verschlafen"),
w("Der Zug war schon abgefahren.","O comboio já tinha partido.|O comboio já tinha saído."),w("Ich bin gerade angekommen.","Acabei de chegar.|Eu acabei de chegar."),w("Wir hatten schon gegessen.","Já tínhamos comido.|Nós já tínhamos comido.|Já tínhamos jantado.|Nós já tínhamos jantado.")],
"Mais-que-perfeito composto: Imperfeito von ter + Partizip (tinha falado, tinhas comido …). Es zeigt, was vor einem anderen Ereignis in der Vergangenheit schon passiert war. Unregelmäßige Partizipien: feito, dito, visto, posto, escrito, aberto, vindo.");

