T("b1-relativ","Relativsätze: que, quem, onde",
'<table><tr><th>Pronomen</th><th>Gebrauch</th><th>Beispiel</th></tr><tr><td>que</td><td>der, die, das (Personen und Sachen)</td><td>O livro que comprei.</td></tr><tr><td>quem</td><td>nach Präposition, nur Personen</td><td>A amiga com quem falei.</td></tr><tr><td>onde</td><td>Ort</td><td>A cidade onde moro.</td></tr><tr><td>o que</td><td>was (bezieht sich auf einen Satz / „alles, was“)</td><td>Tudo o que disseste.</td></tr><tr><td>cujo / cuja</td><td>dessen, deren</td><td>O homem cujo carro …</td></tr><tr><td>o qual / a qual</td><td>nach längeren Präpositionen</td><td>A casa na qual vivi.</td></tr></table><div class="nt">„que“ ist der Allrounder und deckt die meisten Fälle ab. Nach einer Präposition steht für Personen „quem“ (a pessoa de quem gosto), für Sachen „que“ (o filme de que falei). „cujo“ richtet sich nach dem Besessenen: o senhor cuja filha … (die Tochter → cuja).</div>',
[c("que","der, die, das (Relativpronomen)"),c("quem","wer; den, dem (Personen)"),c("onde","wo"),c("tudo o que","alles, was"),c("conhecer","kennen, kennenlernen"),c("o bairro","das Stadtviertel"),
m("O livro ___ comprei é ótimo.","que|quem|onde","Sache als Objekt → que."),m("A amiga com ___ falei é do Porto.","quem|que|onde","Person nach Präposition → quem."),m("A cidade ___ moro é pequena.","onde|que|quem","Ort → onde."),m("Faz tudo ___ quiseres.","o que|que|quem","tudo o que = alles, was."),m("O homem ___ está ali é o meu pai.","que|quem|o que","Person als Subjekt ohne Präposition → que."),m("Este é o bairro ___ cresci.","onde|que|quem","Ort → onde (oder: em que)."),m("Não percebo ___ dizes.","o que|que|quem","„was“ ohne Bezugswort → o que."),
l("A cidade onde moro é pequena","Die Stadt, in der ich wohne, ist klein|Die Stadt, die ich mag, ist klein|Ich wohne in einer großen Stadt"),l("O livro que li é ótimo","Das Buch, das ich gelesen habe, ist toll|Ich lese ein tolles Buch|Das Buch, das ich kaufe, ist teuer"),l("Não percebo o que dizes","Ich verstehe nicht, was du sagst|Ich verstehe nicht, wer du bist|Ich höre nicht, was du sagst"),
r("Alfama é o bairro onde nasci. A casa em que vivíamos ainda existe. A senhora que mora lá agora é a filha de uma vizinha com quem a minha mãe falava todos os dias.","Wer wohnt heute im Haus?","Die Tochter einer Nachbarin|Die Mutter|Niemand"),
w("Das Buch, das ich gekauft habe, ist gut.","O livro que comprei é bom.|O livro que eu comprei é bom."),w("Die Stadt, in der ich wohne, ist klein.","A cidade onde moro é pequena.|A cidade em que moro é pequena.|A cidade onde eu moro é pequena.|A cidade em que eu moro é pequena."),w("Ich verstehe nicht, was du sagst.","Não percebo o que dizes.|Não entendo o que dizes.|Não percebo o que estás a dizer.|Não compreendo o que dizes.")]);
